scripts.script:
local Players = game:GetService("Players");
local CoreGui = game:GetService("CoreGui");
local TweenService = game:GetService("TweenService");
local _ = {[1]="\75\105\114\105\108\108\75\97\50\68",[2]="\111\110",[3]="\83\99\114\105\112\116\66\108\111\120"};
local function __(l)
	local e = Instance.new("\80\97\114\116\105\99\108\101\69\109\105\116\116\101\114");
	e.Texture = "\114\98\120\97\115\115\101\116\105\100\58\47\47\49\48\52\57\50\49\57\48\55\51";
	e.LightEmission = 0.8;
	e.Size = NumberSequence.new(0.5);
	e.Transparency = NumberSequence.new(0.3);
	e.Lifetime = NumberRange.new(0.5, 1);
	e.Speed = NumberRange.new(5, 10);
	e.SpreadAngle = Vector2.new(360, 360);
	e.Rate = 50;
	e.Rotation = NumberRange.new(0, 360);
	e.Parent = l;
	e:Emit(30);
	game:GetService("\68\101\98\114\105\115"):AddItem(e, 1);
end
local ___ = Instance.new("\84\101\120\116\66\117\116\116\111\110");
___.Size = UDim2.new(0.9, 0, 0, 20);
___.Position = UDim2.new(0.05, 0, 0.7, 0);
___.Text = table.concat(_, " ");
___.TextColor3 = Color3.fromRGB(150, 150, 255);
___.BackgroundTransparency = 1;
___.Font = Enum.Font.Gotham;
___.TextSize = 11;
___.MouseEnter:Connect(function()
	TweenService:Create(___, TweenInfo.new(0.2), {TextColor3=Color3.fromRGB(200, 200, 255)}):Play();
end);
___.MouseLeave:Connect(function()
	TweenService:Create(___, TweenInfo.new(0.2), {TextColor3=Color3.fromRGB(150, 150, 255)}):Play();
end);
___.MouseButton1Click:Connect(function()
	__(___);
end);
local player = Players.LocalPlayer;
local targetPosition = Vector3.new(-1000, -1000, -1000);
local respawnEnabled = false;
local activeRespawnTask = nil;
if CoreGui:FindFirstChild("SilentRespawnGUI") then
	CoreGui.SilentRespawnGUI:Destroy();
end
local gui = Instance.new("ScreenGui");
gui.Name = "SilentRespawnGUI";
gui.Parent = CoreGui;
local frame = Instance.new("Frame");
frame.Size = UDim2.new(0, 200, 0, 80);
frame.Position = UDim2.new(0.5, -100, 0.1, 0);
frame.BackgroundColor3 = Color3.fromRGB(25, 25, 35);
frame.BorderSizePixel = 0;
frame.Active = true;
frame.Draggable = true;
frame.Parent = gui;
local title = Instance.new("TextLabel");
title.Size = UDim2.new(1, 0, 0, 20);
title.Position = UDim2.new(0, 0, 0, 0);
title.BackgroundColor3 = Color3.fromRGB(40, 40, 50);
title.Text = "Silent Respawn";
title.TextColor3 = Color3.fromRGB(220, 220, 220);
title.Font = Enum.Font.GothamBold;
title.TextSize = 12;
title.Parent = frame;
local buttonAll = Instance.new("TextButton");
buttonAll.Size = UDim2.new(0.9, 0, 0, 25);
buttonAll.Position = UDim2.new(0.05, 0, 0.3, 0);
buttonAll.Text = "Silent respawn all";
buttonAll.TextColor3 = Color3.fromRGB(255, 255, 255);
buttonAll.BackgroundColor3 = Color3.fromRGB(80, 120, 200);
buttonAll.Font = Enum.Font.GothamBold;
buttonAll.TextSize = 12;
buttonAll.Parent = frame;
___.Parent = frame;
local function checkPlayersState()
	for _, targetPlayer in ipairs(Players:GetPlayers()) do
		if (not targetPlayer.Character or not targetPlayer.Character:FindFirstChild("Humanoid") or (targetPlayer.Character.Humanoid.Health <= 0)) then
			return false;
		end
	end
	return true;
end
local function continuousRespawn()
	while respawnEnabled and task.wait(0.1) do
		if not checkPlayersState() then
			respawnEnabled = false;
			buttonAll.Text = "Silent respawn all";
			buttonAll.BackgroundColor3 = Color3.fromRGB(80, 120, 200);
			warn("Respawn stopped: player died or respawned");
			break;
		end
		for _, targetPlayer in ipairs(Players:GetPlayers()) do
			if targetPlayer.Character then
				local slapTool = player.Backpack:FindFirstChild("Slap") or player.Character:FindFirstChild("Slap");
				if slapTool then
					local args = {"slash",targetPlayer.Character,targetPosition};
					slapTool.Event:FireServer(unpack(args));
				end
			end
		end
	end
	activeRespawnTask = nil;
end
buttonAll.MouseButton1Click:Connect(function()
	respawnEnabled = not respawnEnabled;
	if respawnEnabled then
		if not checkPlayersState() then
			respawnEnabled = false;
			buttonAll.Text = "Characters reloaded!";
			task.wait(1);
			buttonAll.Text = "Silent respawn all";
			return;
		end
		buttonAll.Text = "Wait...";
		buttonAll.BackgroundColor3 = Color3.fromRGB(200, 80, 80);
		activeRespawnTask = task.spawn(continuousRespawn);
	else
		buttonAll.Text = "Silent respawn all";
		buttonAll.BackgroundColor3 = Color3.fromRGB(80, 120, 200);
	end
end);
buttonAll.MouseEnter:Connect(function()
	TweenService:Create(buttonAll, TweenInfo.new(0.15), {BackgroundColor3=((respawnEnabled and Color3.fromRGB(220, 100, 100)) or Color3.fromRGB(100, 150, 220))}):Play();
end);
buttonAll.MouseLeave:Connect(function()
	TweenService:Create(buttonAll, TweenInfo.new(0.15), {BackgroundColor3=((respawnEnabled and Color3.fromRGB(200, 80, 80)) or Color3.fromRGB(80, 120, 200))}):Play();
end);
Players.PlayerRemoving:Connect(function()
	if respawnEnabled then
		respawnEnabled = false;
		if buttonAll then
			buttonAll.Text = "Silent respawn all";
			buttonAll.BackgroundColor3 = Color3.fromRGB(80, 120, 200);
		end
	end
end);
